// And groups predicates with the AND operator between them.
func And(predicates ...predicate.AttributeMappingRule) predicate.AttributeMappingRule {
	return predicate.AttributeMappingRule(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.AttributeMappingRule) predicate.AttributeMappingRule {
	return predicate.AttributeMappingRule(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.AttributeMappingRule) predicate.AttributeMappingRule {
	return predicate.AttributeMappingRule(sql.NotPredicates(p))
}
